            {
              "body": "使用点（x, y 坐标）、线和多边形表示具有清晰空间位置和边界的离散要素（如河流、宗地、植被立地），每个要素赋予 ID 以关联属性。老师 P.6 课堂手写批注举例：dwg（CAD 图纸）、等高线。矢量模型又分地理关系模型或基于对象模型，可具或不具拓扑，涵盖简单要素与复合要素（TIN、动态分段等，详见第 3 章）。",
              "clozeText": "矢量模型用点、线和{{cloze::多边形}}表示边界清晰的{{cloze::离散要素}}（课堂手写举例：{{cloze::dwg CAD 图纸、等高线}}）。",
              "heading": "矢量数据模型定位（含 P.6 课堂手写举例）"
            },
            {
              "body": "使用规则格网和格网元胞（像元）表示空间要素：点=单个元胞，线=一序列相邻元胞，面=连续元胞集合；元胞值对应该位置空间特征，适合表示连续变化现象（如海拔、降水量）。老师 P.6 课堂箭头批注代表：“DEM、数字高程模型”（详见第 4 章）。不同图层必须基于相同坐标系统（如 UTM 分 60 个地带）才能空间匹配。",
              "clozeText": "栅格模型用{{cloze::规则格网和像元}}表示要素，适合表达{{cloze::连续变化}}现象（课堂批注代表：{{cloze::DEM}}）。",
              "heading": "栅格数据模型定位（含 P.6 课堂手写代表）"
            },
            {
              "body": "老师在 P.7 末空白处手写大括号总纲，将表示地面高程的数据模型明确分为两大分支：① 栅格 DEM（规则高程栅格，如图 1.5，详见 Ch4/Ch13）；② 矢量 TIN（不规则三角网，一组互不重叠三角形近似表示地形，如图 1.6，详见 Ch3/Ch13）。",
              "clozeText": "地面数字高程数据模型分为两大分支：{{cloze::栅格 DEM}} 和 {{cloze::矢量 TIN}}。",
              "heading": "地面高程（DEM）两大模型分支（P.7 课堂大括号总纲）"
            },
            {
              "body": "P.16 复习题 9 核心作答：矢量以精确的 (x, y) 坐标点线面描述离散边界，适合网络与精确边界表达；栅格以规则行列矩阵和像元值覆盖全空间，适合连续场模拟与矩阵运算（具体数据结构、拓扑及深入优缺点对比分别见第 3、4、12 章）。",
              "clozeText": "矢量擅长{{cloze::离散要素精确位置与边界}}，栅格擅长{{cloze::连续现象与规则矩阵运算}}，二者在 GIS 项目中常配合使用。",
              "heading": "矢量与栅格核心对比（P.16 复习题 9 骨架）"
            }
