          "flashcard": {
            "a": "矢量数据模型是用点及其 x、y 坐标构造空间要素的数据模型。点为 0 维（仅具位置性质）；线为 1 维（位置+长度，由两节点及中间点组成）；面为 2 维（位置+面积+周长，由闭合不相交线段组成）。要素表达还受地图比例尺与制图规范制约。",
            "hint": "x,y坐标构造；0维位置、1维加长、2维加面积周长",
            "q": "什么是矢量数据模型？点、线、面三种简单几何对象在维度和性质上有何区别？"
          },
