          "points": [
            {
              "body": "矢量数据模型（Vector data model）是用点及其 x、y 坐标构造空间要素的数据模型（P.63 术语表勾画重点），通过点、线和面等几何对象来表示简单的空间要素。",
              "clozeText": "矢量数据模型是用{{cloze::点及其 x、y 坐标}}构造空间要素的数据模型，用点、线和面表示{{cloze::简单空间要素}}。",
              "heading": "矢量数据模型核心定义（P.46, P.63）"
            },
            {
              "body": "三类几何对象的核心差异在于维度与性质：① 点（0 维）：仅具位置性质，由一对坐标表示（如水井、水准点）；② 线/弧（1 维）：除位置外还有长度特性，由两个端点（节点）及其间一系列标记线形态的点构成（如道路、河流、等高线）；③ 面/多边形（2 维）：除位置外还有面积和周长性质，由连接的、闭合的、不相交的线段组成（如伐木场、地块、水体）。",
              "clozeText": "点为{{cloze::零维}}（仅位置），线为{{cloze::一维}}（增长度），面为{{cloze::二维}}（增面积和周长）。",
              "heading": "点、线、面的维度与几何性质（P.46, P.63）"
            },
            {
              "body": "简单要素的几何归类受地图比例尺和机构制图指标影响（P.46-47）：例如 1:1 000 000 地图上的城市表示为点，而 1:24 000 上表示为面；USGS 在 1:24 000 地形图上规定宽小于 40ft 的河流用单线，大于 40ft 用双线。另 Google 地图使用点/线串(linestring)/环线(linering)/多边形，OSM 使用节点(ID+经纬度)/道路。",
              "clozeText": "简单空间要素的表示并非绝对固定，还取决于{{cloze::地图比例尺}}与制图规范指标。",
              "heading": "比例尺效应与跨平台术语（P.46-47）"
            }
          ],
