              "clozeText": "邻接矩阵中 {{cloze::1}} 表示有行节点指向列节点的弧段；关联矩阵中 {{cloze::1}} 表示弧段出射（关联自）该节点，{{cloze::-1}} 表示入射（关联至）该节点。",
