              "body": "美国人口普查局 TIGER 数据库中点称 0 像元、线称 1 像元（含起终点与左右侧地址编码）、面称 2 像元；USGS 的数字化线状图形（DLGs）也是早期内置拓扑的矢量格式。",
              "clozeText": "TIGER 数据库中点、线、面要素分别称为 {{cloze::0 像元、1 像元和 2 像元}}。",
              "heading": "早期内置拓扑应用：TIGER 与 DLGs（P.48-49）"
