              "body": "地理关系数据模型用两个独立系统分别存储空间和属性数据：用图形文件存储空间数据（“地理”，P.50 课堂手写旁批：“点线面画在哪”），用关系数据库（如 INFO 表）存储属性数据（“关系”），两者通过要素标识码（ID）相链接并必须保持同步。",
              "clozeText": "地理关系模型用{{cloze::图形文件}}存储空间数据（点线面画在哪），用{{cloze::关系数据库}}存储属性数据，两者以{{cloze::要素标识码（ID）}}连接并同步。",
