          "points": [
            {
              "body": "与擅长离散要素的矢量相比，对于连续变化的空间现象（如降水量、海拔、土壤侵蚀），最好选择栅格数据模型（又称基于字段的模型）。规则格网的像元值对应位置空间特征，像元值变化反映现象的空间变异（P.70 课堂批注：“两个数据对比”）。",
              "clozeText": "栅格模型又称{{cloze::基于字段的模型}}，最适合表达{{cloze::连续变化}}的空间现象，像元值变化反映现象的{{cloze::空间变异}}。",
              "heading": "连续现象表达与课堂“两个数据对比”（P.70）"
            },
            {
              "body": "栅格又称格网或图像，行列由格网左上角起始（行=y，列=x），每个像元由行列号严格定义。五大基本要素：① 栅格数值（整型栅格存离散类别整数，浮点型栅格存连续值）；② 像元大小（决定分辨率：像元越小分辨率越高，但数据量平方级增大）；③ 像元深度（比特数，如 8bit=256 级或 16bit）；④ 波段（单/多光谱）；⑤ 空间参照系统（经配准的有地理坐标参照栅格）。",
              "clozeText": "栅格五大基本要素为：{{cloze::栅格数值、像元大小、像元深度、波段}}和{{cloze::空间参照系统}}；数值按类型分为{{cloze::整型和浮点型}}。",
              "heading": "五大基本要素与矩阵定位（P.71, P.88）"
            },
            {
              "body": "GIS 中常用的栅格格式数据集包括：数字高程模型（DEM）、卫星图像（如 Landsat、SPOT、Terra ASTER/MODIS、商用 SAR）、数字正射影像（DOQ）、土地覆被数据、二值扫描文件、数字栅格图（DRG）、扫描地图和图形文件（P.70-71）。",
              "clozeText": "常见栅格数据集涵盖 {{cloze::DEM}}、卫星图像、{{cloze::DOQ}}、土地覆被、二值扫描文件、DRG、扫描地图与图形文件。",
              "heading": "常见栅格数据集类型（P.70-71）"
            },
            {
              "body": "优点：在固定格网位置上有明显优势，算法上可视为带行与列的二维数组矩阵，因此比矢量数据更容易进行数据的操作、集合和分析；缺点：表示空间要素的精确位置和边界时呈锯齿状不够理想，且一般需要更大的计算机存储空间（P.71）。",
              "clozeText": "栅格的优点是具固定格网位置、易作为矩阵进行{{cloze::数据操作、集合和分析}}；缺点是{{cloze::精确位置边界}}表达较差且{{cloze::存储空间}}大。",
              "heading": "栅格模型的核心优缺点（P.71）"
            }
          ],
