          "points": [
            {
              "body": "数字高程模型（DEM）由一组均匀间隔的高程数据以栅格格式排列组成（如 ASCII 浮点型栅格），是地形制图和分析（坡度、坡向、河网、流域）的主要数据源。传统生产方法包括使用立体测图仪与航片立体像对，或由等高线地形图插值生成（P.76, P.88）。",
              "clozeText": "DEM 由一组{{cloze::均匀间隔的高程数据}}以栅格格式排列组成，传统制作依赖{{cloze::航片立体像对}}或{{cloze::等高线插值}}。",
              "heading": "DEM 核心定义与传统方法（P.76, P.88）"
            },
            {
              "body": "① 光学传感器（如 Terra ASTER 30m、SPOT 5 HRS 20m）：需短时间内同地区不同方向立体像对；课堂手写重点：“更广范围、例：全球、精度 30m”；② 干涉合成孔径雷达（InSAR）：用两幅及以上 SAR 图像干涉测反射表面高程（如 SRTM 覆盖南北纬 60°~56° 超 80% 大陆，30m/90m；TerraSAR-X 可达 1~10m）；③ 激光雷达（LiDAR）：机载激光扫描仪+GPS+IMU，可检测多次回波测地面与树冠；课堂手写重点：“小范围、例：北京市、分米级”（教材 0.5~2m 级高分辨率，图 4.4 示 3m LiDAR DEM 细节最丰富）。",
              "clozeText": "制作 DEM 三大新技术中，{{cloze::光学传感器}}适用于{{cloze::更广范围（全球，精度 30m）}}；InSAR 用多幅 SAR 图像干涉；{{cloze::激光雷达（LiDAR）}}适用于{{cloze::小范围（如北京市）}}并可达{{cloze::分米级（0.5～2m）}}超高精度。",
              "heading": "制作 DEM 三大新技术及课堂补充对比（P.77-78 手写重点）"
            },
            {
              "body": "数字正射影像（DOQ）是由航片或其他遥感数据制备的数字化影像，其中由照相机镜头倾斜和地形起伏引起的位移已被消除——老师在 P.88 术语末手写批注“（纠正）”（即正射纠正）。USGS DOQ 地面分辨率 1m，常以 GeoTIFF 格式作背景底图或矢量精度核查（P.78, P.87-88）。",
              "clozeText": "DOQ 消除了{{cloze::照相机镜头倾斜}}和{{cloze::地形起伏}}引起的位移（课堂旁批：{{cloze::纠正}}）。",
              "heading": "数字正射影像（DOQ）与课堂“纠正”批注（P.78, P.88）"
            },
            {
              "body": "二值扫描文件（Bi-level scanned file）是仅含数值 1 或数值 0 的扫描图像（如土壤界线扫描图 4.6），可用游程编码高效压缩，在 GIS 中主要用于输入进行线状或面状要素的屏幕数字化（P.79, P.87-88）。",
              "clozeText": "二值扫描文件是仅含数值 {{cloze::1 或 0}} 的扫描图像，在 GIS 中主要用于{{cloze::屏幕数字化}}。",
              "heading": "二值扫描文件（1 或 0）（P.79, P.88）"
            }
          ],
