          "points": [
            {
              "body": "最简单的数据结构，将栅格模型存为按行、列排列的矩阵文件。若栅格像元值连续变化（相邻值很少相同），如 DEM，本方法是理想选择。多波段卫星影像常采用 3 种存储顺序：① 波段序列（.bsq，每波段存一独立文件）；② 波段依行交替（.bil，按行将各波段交替存入单文件）；③ 波段依像元交替（.bip，按像元将各波段依次存入单文件）。",
              "clozeText": "{{cloze::逐个像元编码}}按行、列矩阵存储像元值，是 {{cloze::DEM}} 等连续变化栅格的理想选择；多波段影像有 .bsq、{{cloze::.bil}} 和 .bip 三种格式。",
              "heading": "（1）逐个像元编码（Cell-by-cell encoding，P.81, P.88）"
            },
            {
              "body": "当栅格数据含大量重复像元值（如仅含 0 和 1 的土壤图二值扫描文件）时，可用游程编码（RLE）以“行和组”来记录像元值（每组记录相同像元值的起止位置/连续个数）。RLE 既是编码方法又是无损压缩方法（示例：300dpi 8MB 土壤二值图以 10:1 压缩为 0.8MB）。",
              "clozeText": "游程编码（RLE）以{{cloze::行和组}}记录相邻相同像元值，适合{{cloze::二值扫描文件}}等重复值多的栅格，兼具{{cloze::无损压缩}}效果。",
              "heading": "（2）游程编码（RLE，P.81, P.88）"
            },
            {
              "body": "四叉树（Quad tree）是一种层次化栅格数据结构，将栅格数据递归分解为象限层次（2×2 四等分）：当子象限内所有像元值完全一致时停止细分并用叶节点记录其值，否则继续四分。能有效节省大块均一区域存储空间并支持快速空间索引。",
              "clozeText": "四叉树将栅格数据递归分解为{{cloze::象限层次}}，对{{cloze::大块均质区域}}能同时实现高效压缩与空间检索。",
              "heading": "（3）四叉树（Quad tree，P.81-83, P.88）"
            }
          ],
