          "flashcard": {
            "a": "无损压缩保留像元精确值、可精确重构原图，适合用于 GIS 分析与生成新数据（代表：RLE、PackBits、LZW）；有损压缩不能完全重构原图但压缩率极高，适合做背景影像而非分析（代表：JPEG 8×8斑块易致块状失真）。小波变换将图像看作波并逐步分解为小波，对平缓的低频区将小波系数归零以省空间，对细节丰富的高频区保留高分辨率（代表：MrSID、JPEG 2000）。",
            "hint": "无损可重构做分析 vs 有损高比做底图；小波=高频留细节+低频归零",
            "q": "对比无损压缩与有损压缩的区别与适用场景；结合课堂“高频/低频”批注简述小波变换的压缩原理。"
          },
