          "points": [
            {
              "body": "矢量数据转换为栅格数据称为栅格化（Rasterization），包括 3 个基本步骤：① 建立一个指定像元大小的栅格，覆盖整个矢量数据面积范围，并将所有像元初始值赋予 0；② 改变对应于点、线或多边形边界线的像元值（点赋 1，线赋线值，多边形界线设为多边形值）；③ 用多边形值填充多边形轮廓线内部。其误差取决于算法、像元尺寸和边界复杂度。",
              "clozeText": "栅格化三步骤：① 建指定像元大小栅格并{{cloze::初始赋 0}}；② 改变{{cloze::点、线或多边形边界线}}的像元值；③ 用多边形值{{cloze::填充轮廓线内部}}。",
              "heading": "栅格化三步骤（矢量 → 栅格，P.86, P.88）"
            },
            {
              "body": "栅格数据转换成矢量数据称为矢量化（Vectorization），包括三个基本要素：① 线的细化（把占多像元宽度的扫描栅格线细化到只占 1 个像元宽度）；② 线的提取（决定独立线段的起、止点）；③ 拓扑关系的重建（将提取的线条连接起来并检查数字化错误）。由于结果沿对角线常呈现阶梯状（steplike）特征，常需后续线平滑消除人工痕迹。",
              "clozeText": "矢量化三要素：① {{cloze::线的细化}}（至 1 像元宽）；② {{cloze::线的提取}}（定起止点）；③ {{cloze::拓扑关系的重建}}（后常需线平滑消除阶梯状）。",
              "heading": "矢量化三要素与阶梯状平滑（栅格 → 矢量，P.86, P.88）"
            }
          ],
