          "flashcard": {
            "a": "重采样是以原始图像的像元值或导出值填充新图像每个像元的过程（位置或像元大小改变时必需）。①邻近点插值法：取 1 个最邻近像元，计算最快且保留原像元值，适于土地覆被等类别数据与边缘检测；②双线性插值法：对 4 个相邻像元做三次线性距离加权平均，较平滑；③三次卷积插值法：对 16 个相邻像元用五次多项式插值，图像最平滑但耗时极长（约长 7 倍）。金字塔法通过建立多级降分辨率栅格（基于上述三法之一），可以快速打开大文件、便于概略查看。",
            "hint": "1 个保原值 / 4 个距离加权 / 16 个五次多项式 + 金字塔快开大文件",
            "q": "什么是像元值重采样？对比三种常用重采样方法的原理、优缺点与适用场景，并说明影像金字塔法的作用。"
          },
          "formulas": [],
          "frameworkNodeIds": [
            "fw-1-6-resamp"
          ],
          "id": "ch06-resampling",
          "importance": 3,
          "isCanonical": true,
          "mnemonic": "重采样三法口诀：“一近保类别，四双求平衡，十六卷积最平滑（慢七倍）”；大文件快开靠金字塔（层级越高越概略）。",
          "pages": {
            "primary": [
              125,
              126,
              127
            ],
            "secondary": []
          },
          "points": [
            {
              "body": "重采样是指以原始图像的像元值或导出值填充新图像的每个像元（术语表：将原始影像的值或推导值赋予新转换图像每个像元的过程）。不仅用于卫星影像几何变换，只要发生输入与输出图像的位置（如坐标重投影）或像元大小改变（如 10m 变成 15m），都必须进行重采样以填充输出栅格像元值。",
              "clozeText": "重采样是指以{{cloze::原始图像的像元值或导出值}}填充新图像的每个像元；只要图像的{{cloze::位置（坐标系重投影）}}或{{cloze::像元大小}}发生改变，都必须进行重采样。",
              "heading": "① 重采样定义与必需场景"
            },
            {
              "body": "将原始图像中最邻近像元的值直接填充到新图像的对应像元（图 6.6 中像元 A 取最邻近像元 a 的值）。该方法不需要太多数学计算、速度最快，且具有保留原像元值的特征，对类别数据（如土地覆被类型）及边缘检测等图像处理尤为理想。",
              "clozeText": "{{cloze::邻近点插值法}}采用最邻近像元值估算新像元值，因具有{{cloze::保留原像元值}}的特征且计算量最小，最适用于{{cloze::类别数据（如土地覆被类型）}}与边缘检测。",
              "heading": "② 邻近点插值法（Nearest Neighbor）"
            },
            {
              "body": "二者均将原始图像像元值的距离加权平均值填充到新图像中：双线性插值法通过 4 个最邻近像元的三次线性插值求得距离加权平均；三次卷积插值法则通过五次多项式插值求出 16 个相邻像元的距离加权平均。后者图像普遍更平滑，但处理时间长得多（比一些估算要长 7 倍）。",
              "clozeText": "{{cloze::双线性插值法}}通过 {{cloze::4 个}}相邻像元的距离加权平均估算新像元；{{cloze::三次卷积插值法}}用五次多项式求 {{cloze::16 个}}相邻像元的距离加权平均，结果最平滑但处理时间约长 {{cloze::7 倍}}。",
              "heading": "③ 双线性插值法 vs 三次卷积插值法"
            },
            {
              "body": "金字塔法通过建立不同的金字塔等级（基于 6.4.1 三种重采样方法之一），以显示不同分辨率的大型栅格数据。低分辨率层级（大于 0 级）占内存小、显示更快；放大时再读取高分辨率细节（接近 0 级）。【课堂批注】金字塔法可以快速打开大文件，便于概略查看。",
              "clozeText": "{{cloze::金字塔法（Pyramiding）}}建立不同的金字塔等级以显示不同分辨率的大型栅格数据；其课堂核心要点是{{cloze::可以快速打开大文件（便于概略查看）}}，放大查看细节时再调用接近 {{cloze::0 级}}的高分辨率层级。",
              "heading": "④ 影像金字塔法（Pyramiding）与课堂批注"
            }
          ],
