          "points": [
            {
              "body": "关系数据库是表格或关系表（表格的数学术语）的一个集合，各表格之间通过关键字联系起来（术语表：由表格的集合组成的数据库，用关键字来联系各表格）。相对于平面文件、层次型和网络型数据库，GIS 销售商通常采用关系型数据库来管理属性数据。",
              "clozeText": "关系数据库是{{cloze::表格（关系表）的一个集合}}，各表格之间通过{{cloze::关键字}}联系起来；常见数据库设计的四种类型为平面文件、{{cloze::层次型}}、{{cloze::网络型}}和关系型。",
              "heading": "① 关系数据库定义与四大数据库类型（图 8.6）"
            },
            {
              "body": "主关键字（Primary key）代表基表中能唯一确定一个记录的一个或多个属性，主关键字不能为空，也不能改变。外部关键字（Foreign key）是与基表相链接的表格中参考另一个表主关键字（能唯一确定记录）的一个或多个属性。在 GIS 中两表匹配的关键字常具有相同名称（如要素 ID、PIN、Soil-ID），称为共同关键字。",
              "clozeText": "{{cloze::主关键字}}是基表中唯一确定一条记录的属性，{{cloze::不能为空、不能改变}}；{{cloze::外部关键字}}是参考另一表中主关键字的属性，在 GIS 中常使用同名{{cloze::共同关键字（如要素 ID）}}实现链接。",
              "heading": "② 主关键字、外部关键字与共同关键字"
            },
            {
              "body": "与其他数据库设计相比，关系数据库具有“简单、灵活”的特征及两个突出优点：第一，数据库中的每一表格可与其他表格分开准备、维护和编辑（对按空间单元管理数据的 GIS 尤为重要）；第二，在因查询或分析需要连接表格之前，这些表格仍保持分离，经常需要的表格链接都是临时的，因此对数据管理与处理十分有效。",
              "clozeText": "关系数据库{{cloze::简单、灵活}}的两大突出优点：①每一表格可与其他表格{{cloze::分开准备、维护和编辑}}；②在查询或分析需要连接前各表格{{cloze::保持分离}}，表格链接通常是{{cloze::临时的}}。",
              "heading": "③ 关系数据库“简单、灵活”的两大突出优点"
            }
          ],
