          "summary": "规范化是将一个包含所有属性数据的大表分解成若干小的表格、同时在关系数据库中保持表格之间必要链接的过程，旨在避免冗余与完整性问题、支持独立维护更新并利于形成分布式数据库。",
          "title": "数据库规范化定义、三大目标与拆分逻辑"
