          "points": [
            {
              "body": "表格记录之间的基数（cardinalities）分四类：①一对一：源表与目标表各一条记录唯一互相关联；②一对多：目标表一条记录关联源表多条记录（如一宗地对应多位业主、一地图单元对应多土壤组分）；③多对一：正好相反，多条记录关联另一表一条记录（如多户共享一街道地址、多树种对应同一土壤组分）；④多对多：两表各自多条记录互相关联（如林地与树种）。关系类型直接决定基表选择及地图符号化显示是否完整。",
              "clozeText": "表格间的四种关系类型为{{cloze::一对一}}、{{cloze::一对多}}、{{cloze::多对一}}和{{cloze::多对多}}；当存在{{cloze::一对多}}关系时，直接仅用首个匹配值符号化会漏掉其余信息。",
              "heading": "① 四种关系类型（Cardinalities）及其 GIS 意义"
            },
            {
              "body": "合并（Join）是用两个表格的一个共同关键字或者主关键字和外部关键字把两个表格连成一个表（常把非空间表并入要素属性表）。合并推荐用于“一对一”或“多对一”关系；对“一对多”或“多对多”关系不适用，因为其他表格只有第一条匹配记录值被赋予基表的一条记录。",
              "clozeText": "{{cloze::合并（Join）}}用共同关键字（或主外键）把两表连成一个表，推荐用于{{cloze::一对一}}或{{cloze::多对一}}关系；不适合一对多/多对多是因为只取{{cloze::第一条匹配记录值}}。",
              "heading": "② 合并（Join）的定义与关系限制"
            },
            {
              "body": "关联（Relate）操作只是临时性地把两个表格连接在一起，而各表格保持独立，可同时建立三个或更多表格的联动，优点是对四种关系类型都适合，缺点是会减慢数据存储和访问速度（远程数据库尤慢）。关系类（Relationship class）则是面向对象模型（Geodatabase）中预先定义并存储的关系，在执行关联操作时可自动识别（多对多需建临时表）。",
              "clozeText": "{{cloze::关联（Relate）}}只是{{cloze::临时性地}}连接两表而各表{{cloze::保持独立}}，其优点是对{{cloze::全部四种关系类型}}都适合；Geodatabase 则可预先定义并存储{{cloze::关系类}}。",
              "heading": "③ 关联（Relate）与关系类（Relationship Class）"
            }
          ],
