          "points": [
            {
              "body": "点描法地图（Dot map √）是用统一的点状符号显示空间数据的地图，每个符号代表一个单位值，适合表现离散要素的数量分布（P.183 课堂手写应用：控制点分布）。分级符号地图（Graduated symbol map √）是用不同大小的符号（如圆圈、方形或者三角形）来代表不同数量等级的地图（课堂手写应用：人口分布）。",
              "clozeText": "{{cloze::点描法地图}}用{{cloze::统一的点状符号}}显示空间数据（每符代表一单位值），课堂应用为{{cloze::控制点分布}}；{{cloze::分级符号地图}}用不同大小的符号代表不同数量等级，课堂应用为{{cloze::人口分布}}。",
              "heading": "① 点状定量表达：点描法地图 √ 与分级符号地图 √"
            },
            {
              "body": "等值区域地图（Choropleth map √）是将阴影符号用于收集的数据或统计值，以列举行政单元（如县或州）的地图（课堂手写应用：行政区划图）。统计地图/饼状统计地图（Chart map）是以饼状图或柱状图等统计图作为地图符号的地图，能同时呈现总量与内部分类比重（课堂手写应用：农业、工业比例）。",
              "clozeText": "{{cloze::等值区域地图}}将{{cloze::阴影符号}}用于按{{cloze::行政单元}}收集的统计值，课堂应用为{{cloze::行政区划图}}；{{cloze::饼状统计地图}}以统计图作地图符号，课堂应用为{{cloze::农业、工业比例}}。",
              "heading": "② 面/统计定量表达：等值区域地图 √ 与饼状统计地图"
            },
            {
              "body": "流量地图（Flow map）是以不同宽度的线状符号来显示不同数量的流量数据的地图（课堂手写应用：铁路网/流动网）。等值线地图（Isarithmic map √）是用等值线系统代表一个表面的地图，常用于表示连续变化的空间现象（课堂手写应用：等高线）。",
              "clozeText": "{{cloze::流量地图}}以{{cloze::不同宽度的线状符号}}显示流量数据，课堂应用为{{cloze::铁路网}}；{{cloze::等值线地图}}用{{cloze::等值线系统}}代表连续表面，课堂应用为{{cloze::等高线}}。",
              "heading": "③ 线/连续面定量表达：流量地图与等值线地图 √"
            }
          ],
