              "body": "进入分析阶段的捷径是数据探查。以原始数据为中心的数据探查可使用户查验数据中的总趋势，细察数据子集并关注其间可能存在的关系。数据探查的目的是更好地理解数据，为系统地阐明研究问题和设想提供一个起点；借助交互式动态链接视窗（如“刷亮 Brushing”技术在散点图选点并在地图高亮显示），GIS 中的数据探查涵盖基于地图的数据操作、属性数据查询和空间数据查询三大手段。",
