              "body": "空间合并操作是合并来自两个基于空间关系表格的属性数据（术语表：在两个要素之间基于空间关系的两个表格连接属性数据的一种操作）。如同第 8 章的连接（Join），它把两个表连接起来；但本质区别在于空间合并并不使用一个或几个共同属性字段，而是采用要素之间的空间关系作为连接纽带。",
              "clozeText": "{{cloze::空间合并（Spatial join）}}是在两个要素之间{{cloze::基于空间关系}}连接两个表格属性数据的操作；它不使用{{cloze::共同字段}}，而是直接依靠要素间的空间关系进行匹配。",
