              "body": "空间自相关（Spatial autocorrelation，又称空间联系或空间依赖性）指按照空间赋值状况，测量一个变量的数值之间关系的空间统计量。相邻位置取值相似为正相关，取值相异为负相关，无规律分布则为独立或随机。",
              "clozeText": "{{cloze::空间自相关}}（又称空间联系或空间依赖性）是按照{{cloze::空间赋值状况}}，测量一个变量数值之间{{cloze::关系}}的空间统计量。",
