              "clozeText": "栅格使用{{cloze::规则格网}}覆盖全空间，拥有{{cloze::固定像元位置}}的简单数据结构，不仅{{cloze::计算效率高}}且可用于多种分析，因而常用于大量计算及环境建模工程。",
