              "body": "栅格操作需先定义两项环境参数：① 分析区域范围（特定栅格、Union 并集、Intersect 交集或分析掩模 Analysis mask——掩模将有效区外设 no data 以节省计算时间）；② 输出像元大小（一般取输入栅格中的最大像元，遵循最低分辨率原则，通过重采样统一像元大小）。",
              "clozeText": "栅格数据分析环境需指定{{cloze::分析区域范围}}（如 Union/Intersect/分析掩模）和{{cloze::输出像元大小}}（通常取输入栅格中的{{cloze::最大像元}}，即最低分辨率原则）。",
