              "body": "局域运算（Local operation）是一个像元接一个像元（逐像元）进行的运算，建立了栅格数据分析的核心。分两类：① 单栅格局域运算（如算术/对数/三角/幂函数运算，如将百分比坡度转为度数坡度，以及一对一或区间重新分类 Reclassification）；② 多栅格局域运算（如统计值计算、图层叠加，相当于基于矢量的地图叠置；可通过地图逻辑演算 Map algebra 编写表达式实施）。",
              "clozeText": "{{cloze::局域运算}}是{{cloze::一个像元接一个像元}}进行的运算，建立了栅格数据分析的核心；多栅格局域运算相当于基于矢量的{{cloze::地图叠置}}，常通过地图代数实施。",
