              "body": "自然距离（又称物理距离，Physical distance）量测的是像元中心与源像元之间的直线距离（欧几里得距离），在栅格上通过从源像元以波状连续向外扩张计算得到（受栅格分辨率影响）。计算公式为：像元大小 × √[(x₂ - x₁)² + (y₂ - y₁)²]。",
