            {
              "body": "坡度（Slope）是地表位置上高度变化率的量度，可表达为百分数（垂直距离与水平距离之比×100%）或者度数（垂直距离与水平距离之比的反正切 arctan，0°~90°）。",
              "clozeText": "{{cloze::坡度}}是地表位置上{{cloze::高度变化率}}的量度，可表达为{{cloze::百分数}}或者度数（反正切 arctan）。",
              "heading": "① 坡度定义与两种表达（13.3，P.300）"
            },
            {
              "body": "坡向（Aspect）是斜坡方向（坡面朝向）的量度，量纲是度，从正北 0° 开始顺时针旋转至 360°。因坡向是圆形度量（10° 比 30° 更靠近 360°），分析前常做转换：① 分为 N/E/S/W 共 4 个基本方向，或 N/NE/E/SE/S/SW/W/NW 共 8 个基本方向作类别数据；② 对称数值转换（如 N-S 向设北=0°、南=180°、东/西=90°）；③ 求正弦或余弦值（-1~1）。",
              "clozeText": "{{cloze::坡向}}是斜坡方向的量度（正北 {{cloze::0°}} 顺时针至 360°）；因其为{{cloze::圆形度量}}，常转为 {{cloze::4 个或 8 个基本方向}}、对称数值或正余弦值。",
              "heading": "② 坡向定义与方向转换（P.300 & P.308 双下划线）"
            },
            {
              "body": "影响坡度和坡向量算的三大因子（13.3.3，P.305）：① 用于生成坡度和坡向的 DEM 数据的空间分辨率（或许是最重要因子，分辨率越高如 LiDAR 1.83m 细节越丰富、极值越准确，分辨率降低准确度随之降低）；② DEM 的质量（取决于生产软件与输入控制点质量，如 USGS DEM vs SPOT 立体像对）；③ 坡度和坡向算法（如 8 邻域 Horn 算法 vs 4 邻域 Ritter 算法，另受局部地形陡缓及数据取整影响）。",
              "clozeText": "影响坡度和坡向量算的三大因子：① {{cloze::DEM 空间分辨率}}（最重要）；② {{cloze::DEM 质量}}；③ {{cloze::坡度和坡向算法}}。",
              "heading": "③ 影响坡度和坡向量算的三大因子（13.3.3，P.305）"
            }
