              "body": "常用 Zevenbergen & Thorne 算法对 3×3 窗口作二阶多项式拟合得到系数 D~H：① 剖面曲率沿着最大坡度方向估算（反映坡度沿流向变化，决定水流加速或减速）；② 平面曲率沿着垂直于最大坡度方向估算（反映等高线弯曲，决定水流汇聚或发散）；③ 表面曲率是两者的差值（剖面曲率 - 平面曲率 = -2(D+E)）。",
              "clozeText": "{{cloze::剖面曲率}}沿{{cloze::最大坡度方向}}估算，{{cloze::平面曲率}}沿垂直于最大坡度方向估算，总表面曲率为二者差值。",
