              "clozeText": "地形制图与分析中，高程栅格与 TIN 两种数据模型的区别本质上表现在{{cloze::数据灵活性}}和{{cloze::计算效率}}两个方面。",
              "heading": "① 两大核心比较维度（13.5，P.307–308）"
