          "points": [
            {
              "body": "流域（Watershed）是具有共同出水口的地表水流经的集水区域（P.323 老师箭头旁批：“研究汇水面积”）。流域分析是指用 DEMs 和流向来勾绘河网和流域，包括水流方向计算、流域边界提取和河网的分析（P.334 术语）。",
              "clozeText": "{{cloze::流域}}是地表水排向{{cloze::共同出水口}}的集水区域（即“研究汇水面积”）；{{cloze::流域分析}}是指用 DEMs 和流向勾绘河网和流域。",
              "heading": "① 流域与流域分析定义（P.317, P.323, P.334）"
            },
            {
              "body": "标准衍生链条：① 已填洼 DEM（Filled DEM）：消除小洼地防止流水陷入死胡同；② 流向栅格（Flow direction raster）：记录已填洼高程网上每个像元的水流流向；③ 流量累积栅格（Flow accumulation raster）：显示流向每个像元的上游像元总数；④ 倾泻点/泻流点（Pour points）：生成集水区的出口点（须用 Snap Pour Point 接合到高流量累积河道像元上，否则流域会偏小不完整）。",
              "clozeText": "流域分析四步链条：{{cloze::已填洼 DEM}} → {{cloze::流向栅格}} → {{cloze::流量累积栅格}} → {{cloze::泻流点（倾泻点）}}与河网/流域边界提取。",
              "heading": "② 标准分析链条与核心术语（P.328–333）"
            },
            {
              "body": "流域分析的结果受三大因素影响（14.5，P.329 画圈重点）：① DEM 分辨率（如 10m 比 30m 提取更精细的一级支流河网）；② 流向（商业 GIS 常用 D8 八方向单流向法，山地效果好但在低洼平坦区易产生平行直线河网；另有 D∞ 等多流向法，或通过 stream burning / 加微噪声改善）；③ 流向累积临界值（临界值越大生成河网越稀疏，100~500 像元经验范围通常最接近 1:24000 水系图）。应用：流域管理（美国 WBD 数据集）、水文建模（HEC-HMS）、洪水预报与融雪径流模型。",
              "clozeText": "影响流域分析结果的三大因素：① {{cloze::DEM 分辨率}}；② {{cloze::流向（如 D8 算法）}}；③ {{cloze::流向累积临界值}}（越大河网越稀疏）。",
              "heading": "③ 三大影响因素与核心应用（14.5–14.6，P.329–333）"
            }
          ],
