          "flashcard": {
            "a": "D8 是单流向算法，把中心像元流向分配给距离加权坡降 (Z_中心 - Z_邻域)/d 最大的 1 个邻域像元（正交 d=1 编码东1/南4/西16/北64；对角 d=√2 编码东南2/西南8/西北32/东北128）。先由 DEM 算流向矩阵，再算累积矩阵（外圈无流入为0；各格值 = ∑[来水邻格累积值 + 1]），如 P.323 例题中格 (3,3) 累积值 = 3(个来水箭头) + 1 + 3 + 0 = 7，全图 36 格总汇水出口 (6,5) = 35。",
            "hint": "编码：顺时针东1南4西16北64；坡降=(ΔZ)/d（正交1/斜√2）；累积=指向格(自重1+其前值)求和",
            "q": "简述 D8（八方向法）的编码规则与流向判定公式，并说明如何从水流方向矩阵逐格递推计算流量累积矩阵。"
          },
