            "steps": [
              "【Part 1：D8 方向编码 3×3 栅格（P.323 插图左侧手绘）】中心像元记为 x，顺时针按 2 的幂次排列：上行 [32, 64, 128]（西北、正北、东北）；中行 [16, x, 1]（正西、中心、正东）；下行 [8, 4, 2]（西南、正南、东南）。",
              "【Part 2：3×3 高程邻域最大坡降手算题（P.323 插图右侧手绘）】已知 3×3 高程矩阵为：左列 [8, 7, 9]、中列 [15, 10, 6]、右列 [20, 20, 20]，求中心像元（高程=10）的流向编码。只检验低于 10 的 4 个邻格：① 向西北（8，课堂手写略注向北斜向）：坡降 = (10 - 8) / √2 = √2 ≈ 1.414；② 向正西（7）：坡降 = (10 - 7) / 1 = 3；③ 向西南（9）：坡降 = (10 - 9) / √2 = 1 / √2 ≈ 0.707；④ 向正南（6）：坡降 = (10 - 6) / 1 = 4 √（最大！）。结论：中心像元向正南流，D8 方向编码 = 4。",
              "【Part 3：6×6 原始 DEM → 水流方向矩阵（口诀第一步：“先算每个格子往哪流”）】对下方表1原始 DEM 中每一像元，分别用 (Z_中心 - Z_邻域)/d 选取最大坡降方向填入表2（边缘格若向区域外倾泻如总出口 (6,5)=11 记向南编码 4）。注意核对课堂手写批注差异：第3行第2列（高程 53）向东流向 44（坡降 (53-44)/1 = 9 最大），精确 D8 编码为 1（课堂照片中因连笔箭头在该格叠加写出“32”，第3行第3列 44 向东南流向 22 坡降 (44-22)/√2 = 15.56 最大、编码为 2）。",
              "【Part 4：水流方向矩阵 → 流量累积矩阵（口诀第二步：“再算每个格子累积流值”）】按课堂口诀与 ArcGIS 标准规则：每个像元自身产流权重为 1，输出格记录的是流向它的上游像元总数（不含自身）。外圈无上游流入的像元一般记 0（若外圈格有内侧邻格流入则按实计，如第4行第6列=1、第6行=0,2,4,7,35,1）。计算公式：格值 = 指向它的箭头数（各指向邻格自身权重1）+ 这些上游邻格原有的累积值之和。",
              "【Part 5：课堂画圈核心节点逐格验算】① 课堂重点画圈格 (3,3)=7：由流向矩阵可见，指向 (3,3) 的有 3 个邻格——(2,2)（累积值 1）、(3,2)（累积值 3）、(4,2)（累积值 0）。代入课堂手写算式：7 = 3（3个来水箭头，各自重1）+ 1 + 3 + 0（课堂笔注“7 = 3 + 1 + 3 + 0”，正是“箭头数 + 前次上游值”的直接体现！）；② 验算 (4,4)=20：有 4 格指向它，即 (3,3)=7、(3,4)=5、(4,3)=0、(3,5)=4 → 20 = 4 + (7 + 5 + 0 + 4)；③ 验算 (5,5)=24：有 3 格指向它，即 (4,4)=20、(4,5)=0、(4,6)=1 → 24 = 3 + (20 + 0 + 1)；④ 验算总出水口 (6,5)=35：有 3 格指向它，即 (5,5)=24、(6,4)=7、(6,6)=1 → 35 = 3 + (24 + 7 + 1) = 35（6×6 共 36 格，除自身外其余 35 格全部汇入此出口；提示：课堂照片右下角将 (6,6) 误抄作 2，但由总格数 36-1=35 及 (5,6) 仅贡献 1 可证实 (6,6) 准确值为 1）。"
            ],
