            "a": "空间插值是用已知点（控制点）的数值来估算其他未知点数值的过程，即将离散点数据转换为连续面数据（格网化）。两大基本条件是“已知点”和“插值方法”。三大分类维度：①范围上分全局插值法（用全部已知点估总趋势）vs 局部插值法（用样本点估短程变化）；②点值穿行上分精确插值法（生成表面穿过全部已知点）vs 非精确/近似插值法（估算值与已知值不同）；③误差评价上分确定性插值（不提供预测误差检验）vs 随机性插值（用估计变异评估预测误差）。",
