              "clozeText": "整体拟合法包含两类：{{cloze::趋势面分析}}基于已知点坐标和多项式方程拟合近似面；{{cloze::回归模型}}用一系列{{cloze::自变量}}去估算一个因变量（常衔接第18章空间建模）。",
