              "body": "局部拟合先定控制点数（如默认 7~12 个），再通过最近邻点、半径搜索或四/八分象限法选点（图 15.5）。泰森多边形（又称冯罗诺多边形 Voronoi polygons）通过先连已知点为德劳内（Delaunay）三角形、再画各边中垂线生成，确保多边形内任意未采样点距多边形内已知点最近、距其他已知点更远，属精确插值但呈阶梯突变（常用于均雨量与医院服务区分析）。",
              "clozeText": "{{cloze::泰森多边形}}（又称{{cloze::冯罗诺多边形}}）确保多边形内任意未采样点与该多边形内已知点距离最近，通常先构造{{cloze::Delaunay 三角形}}再作各边中垂线生成。",
