            "a": "克里金法是用于空间插值的地统计学（局部随机）方法，利用半变异图度量空间相关性赋权，并能用估计的预测误差评估预测质量。核心概念：①普通克里金法：假定不存在漂移或趋势，只关注空间相关要素；②块金（块金效应）：半变异图上距离为 0 处的半变异值；③门槛值：半变异达到恒定时的半变异值；④偏门槛值（偏基台值）：半变异图中门槛值与块金的差值；⑤变程：半变异达到恒定时的距离。",
