          "points": [
            {
              "body": "克里金法（Kriging）是一种用于空间插值的地统计学方法，也是局部拟合法中唯一的随机性方法。它假定属性的空间变异同时包含三类成分：空间相关因素、表征趋势的“漂移”或结构、以及随机误差。与确定性方法不同，克里金法可用估计的预测误差（方差/标准误差）评估预测质量，常用于将 LiDAR 点数据转换为 DEM。",
              "clozeText": "克里金法是一种用于空间插值的{{cloze::地统计学}}方法（局部唯一随机法），它利用估计的{{cloze::预测误差}}来评估预测质量，假定空间变异含空间相关因素、{{cloze::漂移}}（趋势）和随机误差。",
              "heading": "① 地统计学本质、三成分与误差评价优势（P.357 画圈重点）"
            },
            {
              "body": "克里金法通过半变异（Semivariance）定量测度已知点间的空间自相关，在区间分组（Binning，按距离和方向归并）后绘制半变异图（考虑方向差异即各向异性 Anisotropy）。核心四参数：①块金（Nugget / 块金效应）：距离为 0 处的半变异值（反映测量误差或微尺度变异）；②门槛值（Sill）：半变异达到恒定时的数值；③偏门槛值（Partial sill / 偏基台值）：门槛值与块金的差值；④变程（Range）：半变异达到恒定时的距离，超过变程则无空间相关性。",
              "clozeText": "半变异图中，距离为 0 处的半变异值称为{{cloze::块金}}（块金效应），半变异达到恒定时称为门槛值，而门槛值与块金的差值称为{{cloze::偏门槛值}}（偏基台值）；达到恒定时的距离称为{{cloze::变程}}。",
              "heading": "② 半变异图与核心术语：块金、偏门槛值、变程（P.368–369 术语表）"
            },
            {
              "body": "三种基本克里金：①普通克里金法（Ordinary Kriging）：假定不存在漂移或趋势，专注空间相关要素（最常用）；②泛克里金法（Universal Kriging）：假定存在漂移或趋势成分；③简单克里金法：假定整体均值已知。此外还有指示性克里金（二进制概率）、块克里金（区域均值）以及引入高程等次要相关变量的协克里金法（Co-Kriging）。",
              "clozeText": "{{cloze::普通克里金法}}假定不存在漂移或趋势、专注空间相关要素；{{cloze::泛克里金法}}则假定存在漂移或结构成分；引入辅助协变量提升主变量精度称为{{cloze::协克里金法}}。",
              "heading": "③ 普通克里金法 vs 泛克里金与协克里金（P.366/368–369）"
            },
            {
              "body": "IDW 仅按几何距离反比分配固定权重且不顾样本空间分布结构；克里金法则以拟合半变异图模型得到的空间自相关函数计算最优无偏权重（既考虑估算点到控制点的距离，也考虑控制点彼此间的空间集聚冗余），还能同时输出各点预测方差。",
              "clozeText": "与 IDW 仅依几何距离赋权不同，克里金法基于拟合{{cloze::半变异图}}所得的空间相关性赋予最优权重，并能同步输出每个预测点的{{cloze::标准误差}}。",
              "heading": "④ 克里金法与 IDW 赋权机制对比（P.369 复习题重点）"
            }
          ],
