          "flashcard": {
            "a": "比较插值方法的两种常用统计技术是交叉验证和验证。留一交叉验证对每种方法重复三步：（1）从数据集中除去一个已知点的测量值；（2）用保留点的测量值估算除去点的值；（3）比较原始值和估算值，计算估算值的预计误差。随后计算均方根误差（RMS，越小越好）及克里金专用的标准均方根误差（标准 RMS，越接近 1 越好）。验证则是将控制点分成建模组和验证组两组样本来比较。",
            "hint": "一除、二估、三算误差，诊断看 RMS（越小越好）与标准 RMS（近 1）。",
            "q": "比较空间插值方法有哪两种常用统计技术？请默写留一交叉验证的三个操作步骤及结果评价指标。"
          },
          "formulas": [
            "均方根误差（式 15.18）：RMS = √[ (1/n) ∑_{i=1}^n (z_{i,act} - z_{i,est})^2 ]",
            "标准均方根误差（式 15.19，仅克里金）：标准 RMS = √[ (1/n) ∑_{i=1}^n ((z_{i,act} - z_{i,est})^2 / s^2) ] = RMS / s"
          ],
