          "points": [
            {
              "body": "交叉验证和验证是进行插值方法比较时两种常用的统计技术。在数据缺乏区域不同插值方法差值最大，因此必须用统计诊断指标比较优劣（同时需兼顾表面清晰性等视觉质量）。验证法将控制点划分为两组样本：一组用于建立插值模型，另一组独立验证模型准确度；当已知点太少难以拆分成两组样本时，验证法便不适用。",
              "clozeText": "{{cloze::交叉验证}}和{{cloze::验证}}是插值方法比较的两种常用统计技术；验证法将控制点分为建立模型与检验精度两组样本，但当{{cloze::已知点数目太少}}时便不适用。",
              "heading": "① 交叉验证 vs 验证（适用条件区分，P.366–367/369）"
            },
            {
              "body": "交叉验证（留一法）对被比较的每种插值方法，针对每个已知点重复以下三步骤：（1）从数据集中除去一个已知点的测量值；（2）用保留点的测量值估算除去点的值；（3）比较原始值和估算值，计算出估算值的预计误差。最后汇总全部点计算诊断统计值。",
              "clozeText": "留一交叉验证三步骤：（1）从数据集中{{cloze::除去一个已知点}}的测量值；（2）用{{cloze::保留点}}的测量值估算除去点的值；（3）比较{{cloze::原始值和估算值}}，计算估算值的预计误差。",
              "heading": "② 留一交叉验证三步骤（P.366 标号斜线必背重点）"
            },
            {
              "body": "两个常用诊断统计值：①均方根（RMS）误差：量化已知值与估算值平均偏差，RMS 越小，插值效果越好（适用于所有精确局部拟合法）；②标准均方根（标准 RMS）误差：RMS 除以预测标准差 s，因计算需用预测方差 s²，故仅适用于克里金法——较优克里金模型应满足 RMS 较小且标准均方根接近于 1（表明估计标准误差有效度量了预测不确定性）。",
              "clozeText": "评价插值准确度的两个统计量为{{cloze::均方根（RMS）误差}}（值越小越好）和{{cloze::标准均方根误差}}；后者因需要估算值的方差 s² 故{{cloze::只能用于克里金法}}，且较优克里金模型应接近于 1。",
              "heading": "③ 均方根误差（RMS）与标准 RMS 判别准则（P.366–367）"
            }
          ],
