            "a": "地理编码是对存储于表格中含位置字段的数据进行空间位置赋值的过程；地址地理编码（又称地址匹配）是其最常见形式，指将街道地址以点要素形式表示在地图上的过程。必须具备的两个数据集：①街道地址的表格数据（一条记录对应一个地址）；②参照数据库（由街道地图路网及街道名称、左右两侧地址范围和邮政编码等属性组成）。",
            "hint": "区分“表格赋坐标(广义)”与“街道变点(地址匹配)”；两数据集＝地址表＋路网参照库。",
