          "points": [
            {
              "body": "广义的地理编码（Geocoding）指对存储于表格中的数据进行空间位置赋值的过程（表格中含有描述位置的字段，如把邮政地址转为成对经纬度）；最常见的形式是地址地理编码（Address geocoding），也称为地址匹配（Address matching），即将表格中的街道地址以点要素形式标示在地图上。",
              "clozeText": "{{cloze::地理编码}}是对存储于表格中含位置字段的数据进行{{cloze::空间位置赋值}}的过程；最常见的{{cloze::地址地理编码}}（又称地址匹配）是将街道地址用{{cloze::点要素}}表示在地图上。",
              "heading": "① 地理编码 vs 地址地理编码（地址匹配）概念辨析（P.377/392 重点）"
            },
            {
              "body": "地址地理编码必需两个输入数据集：①街道地址的表格数据（一条记录对应一个地址，包含名称、街道地址、邮编等字段）；②参照数据库（由街道地图路网及每条街道的属性组成，如街道名称、左右两侧起止地址号码范围和邮政编码；美国常源自 TIGER/Line 文件或商业 TomTom/NAVTEQ 数据库）。通过比较待匹配地址与参照数据库确定点位置。",
              "clozeText": "地址地理编码需要两个数据集：第一个是{{cloze::街道地址的表格数据}}（一条记录对应一个地址）；第二个是{{cloze::参照数据库}}，由街道地图及街道名称、{{cloze::地址范围}}和邮政编码等属性组成。",
              "heading": "② 地址地理编码必需的两大数据集（P.377–378 & 手写框架重点）"
            },
            {
              "body": "标准地址匹配经历三个阶段：①预处理（将地址分解为街道编码、方向前缀、街名、街道类型、邮编等并作标准化与 Soundex 拼写容错）；②匹配（在参照数据库检索匹配街段，通过线性内插沿街道两侧门牌号范围定位）；③标绘（生成带 x,y 坐标的点要素输出）。",
              "clozeText": "地址匹配过程通常包括{{cloze::预处理}}（解析和地址标准化）、{{cloze::匹配}}（沿地址范围线性内插）和{{cloze::标绘}}三个阶段。",
              "heading": "③ 地址匹配三阶段与线性内插机制（P.379）"
            },
            {
              "body": "除街道地址匹配外，常见变异形式包括：交叉点匹配（又称街角匹配）、地块级地理编码（匹配地块号与几何中心）、邮政编码地理编码（匹配邮编中心）、照片地理编码（附加位置信息）、地名别名地理编码，以及反向地理编码（将经纬度坐标转换为描述性地址）。",
              "clozeText": "地理编码的变异形式包括{{cloze::交叉点匹配}}（街角匹配）、地块级/邮政编码/照片/地名别名地理编码，以及将经纬度转为描述性地址的{{cloze::反向地理编码}}。",
              "heading": "④ 地理编码的六大变异形式（P.382/392–393 术语表）"
            }
          ],
