          "points": [
            {
              "body": "动态分段（Dynamic segmentation）是计算路径上事件位置的数据模型与过程（第1章 P.15、第16章 P.392）。与地理编码一样，它能利用缺少 x,y 坐标而以已知点（如里程碑）线性距离报告的数据源进行空间定位，其核心设计宗旨是将一维线性参照系统与二维投影坐标系统 (x,y) 汇集在一起（第1章 P.7 图1.7、第16章 P.377）。",
              "clozeText": "动态分段是计算{{cloze::路径上事件位置}}的过程，旨在把缺少 x,y 坐标的{{cloze::线性参照系统}}（如沿路里程）与二维{{cloze::投影坐标系统}}汇集在一起。",
              "heading": "① 核心定位与双量测系统融合（整合 P.7/P.15/P.377/P.392）"
            },
            {
              "body": "路径（Route）是线性量测系统与其几何特性一起存储的复合线要素，区别于普通线要素的关键在于拥有度量系统（Measure system，第3章 P.61）。在 Coverage 中路径由区段记录始/到位置与始/到测值（F-MEAS/T-MEAS）；在 Shapefile 与 Geodatabase 中则直接用带有 m 值（线性测度）的聚合线（x, y, m）表示。路径按拓扑形态分为简单路径、组合路径、循环路径和分割路径。",
              "clozeText": "路径与其他线要素的本质区别在于它拥有{{cloze::度量系统}}，可将线性测量引入投影坐标系；在 Geodatabase 中以带 {{cloze::m 值}}（测量值）的聚合线存储路径动态位置对象。",
              "heading": "② 底层要素一：路径（Route）与线性度量系统（整合第3章 P.61–62 & P.393）"
            },
            {
              "body": "事件（Events）是沿路径发生的线性属性，无需物理切分或复制底层道路线要素即可将多套互不相同的分段属性挂接到同一条路径上，分为：①点事件（Point events）：发生在路径上单个位置点（由单一 m 值定位），如交通事故、停车标志、公路休息区；②线事件（Line events）：涵盖路径的一段区间（由始测值与到测值定位），如路面状况、限速路段、沿河水质。",
              "clozeText": "沿路径发生的属性称为{{cloze::事件}}，分为在单一位置点发生的{{cloze::点事件}}（如交通事故）和涵盖部分路径区间的{{cloze::线事件}}（如路面状况）。",
              "heading": "③ 底层要素二：事件表分类（点事件 vs 线事件，P.385/392–393）"
            },
            {
              "body": "动态分段主要用于显示、查询和分析与交通运输（如事故聚集分析、限速与事故多发段关系叠加）及自然资源（如沿河水文水质、步道路况）相关的数据（第1章 P.10、第16章 P.392）。两个事件图层间可执行类似矢量叠置的动态路段相交分析。",
              "clozeText": "动态分段主要用于显示、查询和分析与{{cloze::运输}}（及自然资源）相关的数据，多个{{cloze::事件图层}}之间还可执行类似矢量叠置的区间组合分析。",
              "heading": "④ 典型应用与多事件叠置分析（整合 P.10 & P.392）"
            }
          ],
