          "points": [
            {
              "body": "网络（Network）是一种线要素系统，线要素带有用于目标流（如交通流）的恰当属性，必须具备拓扑连通性（第1章 P.7）。建立矢量路网需经过网络拼接与编辑：纠正中心线偏移、删除多余伪节点（保留属性变更处的必要伪节点），并赋予链路阻抗、单行道方向、限速及十字路口转弯表。",
              "clozeText": "{{cloze::网络}}是一种线要素系统，其线要素具备用于{{cloze::目标流}}的恰当属性；构建可用矢量路网需在网络拼接中赋予{{cloze::链路阻抗}}、单行道、限速和转弯阻抗等网络属性。",
              "heading": "① 网络定义与矢量路网拼接属性（P.407–410/418）"
            },
            {
              "body": "最短路径分析是在网络中寻找节点间累积阻抗最小的路径（P.410 画圈“累积阻抗”及 P.419 术语重点）。链路阻抗既可由自然距离（得出最短路线）也可由通行时间（得出最快路线）量测，十字路口还包含转弯阻抗（完成转弯耗费的时间）。分析以表示直连阻抗（不直连记 ∞）的阻抗矩阵为基础，最常用 Dijkstra 算法求解。",
              "clozeText": "最短路径分析是在网络中寻找节点间{{cloze::累积阻抗}}最小的路径（可表示{{cloze::最短}}或{{cloze::最快}}的路线），它基于阻抗矩阵，最常用的求解算法是 Dijkstra 算法。",
              "heading": "② 最短路径分析定义、累积阻抗与 Dijkstra 算法（P.410/419 重点）"
            },
            {
              "body": "基于相同拓扑路网属性还可开展三类重要网络分析：①旅行推销员问题（TSP）：以每个站点只经过一次并返回出发点为条件寻找最佳路径；②配置分析：按最大允许阻抗划分网络服务区；③定位–配置（Location-allocation）：用多组目标与约束条件使设施供需相匹配（如最小距离模型、最大覆盖模型，第18章注释栏 18.1 再作关联）。",
              "clozeText": "衍生网络分析包括：每站仅经一次并返回起点的{{cloze::旅行推销员问题（TSP）}}、划分服务区的配置分析，以及用多组目标约束使供需匹配的{{cloze::定位–配置}}分析。",
              "heading": "③ 衍生网络分析：TSP、服务区配置与定位–配置（P.418–419）"
            }
          ],
