            "a": "建模过程（老师课堂手写精髓：“建立一个台架”）包含三大步骤：①明确建模目的（确定模拟对象、目的与时空尺度，组建基本结构）；②把模型分解成各种元素（定义属性与相互作用流程图，并将数学方程与 GIS 工具集成计算）；③模型的应用与校准（运行并反复调整参数对比观测差异，再用敏感性分析及独立数据集完成验证）。模型大类包括描述/规则、确定/随机、静态/动态、推论/归纳四对分类。",
