          "points": [
            {
              "body": "模型是对现实世界现象或系统的简化表示（地图及矢量/栅格/关系数据库本质皆为模型）；第18章聚焦“空间显式模型”以及 GIS 在建模中的作用。按表 18.1（P.429）与术语表（P.443），模型可按四大维度归类：描述模型（描现状）vs 规则模型（测未来）、确定模型（唯一值）vs 随机模型（概率与误差）、静态模型（时间常数）vs 动态模型（随时间演化）、推论模型（科学理论前提）vs 归纳模型（实验观察归纳）。",
              "clozeText": "GIS 模型是对现象或系统的简化表示，可按四对维度分类：{{cloze::描述的与规则的}}、{{cloze::确定的与随机的}}、动态的与静态的、{{cloze::推论的与归纳的}}。",
              "heading": "① 模型本质与四大分类维度（表 18.1 & P.443 术语）"
            },
            {
              "body": "老师在 P.429 `18.1.2 建模过程` 处画圈并手写核心总结“建立一个台架”，即先搭起整体概念与逻辑结构，严格遵循三步骤：①明确建模目的（确定研究问题、模拟现象与时空尺度，用概念图表组基本结构）；②把模型分解成各种元素（用流程图定义元素属性与相互作用，集成数学方程与 GIS 工具）；③模型的应用与校准（不断对比输出与观测差异调整参数，并做敏感性分析与独立数据验证）。",
              "clozeText": "GIS 建模过程（课堂批注“{{cloze::建立一个台架}}”）包含三步：①{{cloze::明确建模目的}}；②{{cloze::把模型分解成各种元素}}；③模型的应用与校准（含独立数据集验证）。",
              "heading": "② 建模三大步骤与手写“建立一个台架”（P.429 画圈+批注重点）"
            },
            {
              "body": "GIS 在建模中的作用：集成处理多源数据并支持数据探查与可视化；根据模拟对象与效率选择数据模型——连续变化现象（土壤侵蚀、积雪）、影像/DEM 主导或大量复杂计算首选栅格模型（呼应第12章 P.269 问答题），离散形状及拓扑路网分析首选矢量模型，且可借助 GIS 互转（如点插值为栅格再转图层）。",
              "clozeText": "模拟随空间连续变化现象或涉及高强度复杂计算时首选基于{{cloze::栅格}}的模型（呼应第12章 P.269）；涉及拓扑路网（如旅游路线）或边界清晰离散现象则首选基于{{cloze::矢量}}的模型。",
              "heading": "③ GIS 在建模中的作用与栅格/矢量选型（P.430 & 第12章联动）"
            },
            {
              "body": "二值模型与指数模型能完全在 GIS 内部建立；回归模型与过程模型常需将 GIS 与外部专业/统计程序联结。结合方式分三种（P.431/443）：①松散联结（通过数据文件导入导出传递）；②紧密联结（提供共享共同用户界面菜单）；③嵌入系统（通过共享存储器与接口完全捆绑，如 ArcGIS 地统计分析扩展）。",
              "clozeText": "四类模型中，{{cloze::二值模型与指数模型}}可完全在 GIS 内部建立，回归和过程模型常需与外部程序联结；三种结合方式为{{cloze::松散联结}}、紧密联结和{{cloze::嵌入系统}}。",
              "heading": "④ GIS 与其他建模程序的三种结合方式（P.431/443）"
            }
          ],
